"use client";

import { useEffect, useMemo, useRef, useState, type KeyboardEvent } from "react";

import { ProvenanceBadge } from "@/components/common/badges";
import { cn } from "@/lib/utils";

/*
 * Planet or impostor? Four sources of a repeating dip, each with a small animated scene and the shape
 * of light curve it produces. All curves here are illustrations generated by code, labelled as such.
 */

type Kind = "planet" | "binary" | "blend" | "instrument";

const CASES: { id: Kind; label: string; verdict: string; text: string; tell: string }[] = [
  { id: "planet", label: "Planet transit", verdict: "What the model looks for",
    text: "A planet blocks a small, steady fraction of the star's light once per orbit.",
    tell: "Shallow and flat-bottomed (U-shaped), the same depth every orbit, and nothing half an orbit later." },
  { id: "binary", label: "Eclipsing binary", verdict: "Impostor",
    text: "Two stars orbit each other and take turns dimming one another.",
    tell: "Deeper and V-shaped, with a second, shallower eclipse half an orbit after the first." },
  { id: "blend", label: "Background blend", verdict: "Impostor",
    text: "A faint eclipsing pair behind the target leaks its light into the target's pixels.",
    tell: "Diluted until it is as shallow as a planet, but it keeps the V shape and the secondary eclipse." },
  { id: "instrument", label: "Instrument artefact", verdict: "Impostor",
    text: "Pointing drift, momentum dumps and detector effects repeat on the spacecraft's schedule.",
    tell: "Steps, ramps and spikes that line up with the spacecraft's clock rather than any orbit." },
];

/** Relative flux over one cycle (phase 0..1) for each case. */
function flux(kind: Kind, ph: number): number {
  const u = (c: number, w: number) => Math.min(1, Math.abs(ph - c) / w);           // 0 at centre, 1 outside
  switch (kind) {
    case "planet": {
      const x = u(0.25, 0.06);
      return x >= 1 ? 1 : 1 - 0.012 * (1 - Math.pow(x, 6));                      // flat bottom, short ingress
    }
    case "binary":
      return 1 - 0.09 * Math.max(0, 1 - u(0.25, 0.05)) - 0.035 * Math.max(0, 1 - u(0.75, 0.05));   // V + secondary
    case "blend":
      return 1 - 0.012 * Math.max(0, 1 - u(0.25, 0.05)) - 0.0045 * Math.max(0, 1 - u(0.75, 0.05));
    case "instrument": {
      const ramp = 0.006 * ((ph * 3) % 1);                                         // thermal ramp, resets 3x a cycle
      const dump = Math.abs((ph * 3) % 1 - 0.02) < 0.012 ? -0.012 : 0;             // momentum-dump spike
      return 1 - ramp + dump;
    }
  }
}

const W = 520, GRAPH = { x: 40, y: 170, w: 440, h: 110 };
const DEPTH_RANGE = 0.1;

function Scene({ kind, phase }: { kind: Kind; phase: number }) {
  const cx = W / 2, cy = 76;
  const a = 2 * Math.PI * phase;
  if (kind === "planet") {
    // phase 0.25 is mid-transit, matching the curve below
    const px = cx + 150 * Math.sin(a - Math.PI / 2), pfront = Math.cos(a - Math.PI / 2) > 0;
    const planet = <circle cx={px} cy={cy + 6} r="7" fill="#050505" stroke="rgba(255,255,255,0.25)" />;
    return (
      <g>
        <ellipse cx={cx} cy={cy + 6} rx="150" ry="14" fill="none" stroke="rgba(255,255,255,0.12)" strokeDasharray="2 5" />
        {!pfront && planet}
        <circle cx={cx} cy={cy} r="46" fill="url(#cmp-star)" />
        {pfront && planet}
      </g>
    );
  }
  if (kind === "binary" || kind === "blend") {
    const s = kind === "blend" ? 0.42 : 1;
    const ox = kind === "blend" ? 120 : 0, oy = kind === "blend" ? -26 : 0;
    const t = 2 * Math.PI * (phase - 0.25);
    const A = { x: cx + ox + 52 * s * Math.sin(t), y: cy + oy, front: Math.cos(t) > 0 };
    const B = { x: cx + ox - 52 * s * Math.sin(t), y: cy + oy, front: Math.cos(t) <= 0 };
    const big = <circle key="a" cx={A.x} cy={A.y} r={34 * s} fill="url(#cmp-star)" opacity={kind === "blend" ? 0.55 : 1} />;
    const small = <circle key="b" cx={B.x} cy={B.y} r={24 * s} fill="url(#cmp-star-cool)" opacity={kind === "blend" ? 0.55 : 1} />;
    return (
      <g>
        {kind === "blend" && <circle cx={cx - 40} cy={cy + 4} r="44" fill="url(#cmp-star)" />}
        {kind === "blend" && <circle cx={cx - 40} cy={cy + 4} r="78" fill="none" stroke="rgba(255,255,255,0.18)" strokeDasharray="3 5" />}
        {A.front ? [small, big] : [big, small]}
      </g>
    );
  }
  // instrument: the star is steady; the telescope's pointing jitters on its own schedule
  const jitter = Math.abs((phase * 3) % 1 - 0.02) < 0.04 ? 6 : 0;
  return (
    <g>
      <circle cx={cx + 90} cy={cy} r="40" fill="url(#cmp-star)" />
      <g transform={`translate(${cx - 120 + jitter * 0.4} ${cy - 6 + jitter * 0.2}) rotate(${-8 + jitter})`}>
        <rect x="-46" y="-12" width="92" height="24" rx="4" fill="#16171b" stroke="rgba(255,255,255,0.3)" />
        <rect x="46" y="-16" width="10" height="32" rx="2" fill="#0d0e11" stroke="rgba(255,255,255,0.3)" />
        <rect x="-70" y="-3" width="22" height="6" fill="rgba(143,180,255,0.6)" />
      </g>
      <text x={cx - 120} y={cy + 46} fill="#a3a6ad" fontSize="10" textAnchor="middle" fontFamily="var(--font-geist-mono), monospace">
        {jitter ? "momentum dump" : "pointing drift"}
      </text>
    </g>
  );
}

export function SignalComparison() {
  const [kind, setKind] = useState<Kind>("planet");
  const [phase, setPhase] = useState(0.25);
  const ref = useRef<HTMLDivElement>(null);
  const tabs = useRef<(HTMLButtonElement | null)[]>([]);

  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    let raf = 0, t0 = 0;
    const tick = (now: number) => {
      t0 ||= now;
      setPhase(((now - t0) / 7000) % 1);
      raf = requestAnimationFrame(tick);
    };
    const io = new IntersectionObserver(([e]) => {
      cancelAnimationFrame(raf);
      if (e.isIntersecting) raf = requestAnimationFrame(tick);
    });
    if (ref.current) io.observe(ref.current);
    return () => { cancelAnimationFrame(raf); io.disconnect(); };
  }, []);

  const curve = useMemo(() => Array.from({ length: 301 }, (_, i) => {
    const ph = i / 300;
    const y = GRAPH.y + 10 + ((1 - flux(kind, ph)) / DEPTH_RANGE) * (GRAPH.h - 20);
    return `${i ? "L" : "M"}${(GRAPH.x + ph * GRAPH.w).toFixed(1)},${y.toFixed(1)}`;
  }).join(" "), [kind]);

  const current = CASES.find((c) => c.id === kind)!;
  const markerY = GRAPH.y + 10 + ((1 - flux(kind, phase)) / DEPTH_RANGE) * (GRAPH.h - 20);

  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    const i = CASES.findIndex((c) => c.id === kind);
    const next = e.key === "ArrowRight" ? (i + 1) % CASES.length : e.key === "ArrowLeft" ? (i - 1 + CASES.length) % CASES.length
      : e.key === "Home" ? 0 : e.key === "End" ? CASES.length - 1 : -1;
    if (next < 0) return;
    e.preventDefault();
    setKind(CASES[next].id);
    tabs.current[next]?.focus();
  };

  return (
    <div ref={ref} className="grid gap-6 lg:grid-cols-[1fr_1.35fr]">
      <div>
        <div role="tablist" aria-label="Sources of a repeating dip" className="flex flex-wrap gap-2" onKeyDown={onKey}>
          {CASES.map((c, i) => (
            <button key={c.id} ref={(el) => { tabs.current[i] = el; }} role="tab" type="button" id={`cmp-tab-${c.id}`}
                    aria-selected={kind === c.id} aria-controls="cmp-panel" tabIndex={kind === c.id ? 0 : -1}
                    onClick={() => setKind(c.id)}
                    className={cn("glass min-h-11 rounded-full px-4 text-sm transition-colors",
                                  kind === c.id ? "text-foreground ring-1 ring-white/40" : "text-muted-foreground hover:text-foreground")}>
              {c.label}
            </button>
          ))}
        </div>
        <div id="cmp-panel" role="tabpanel" aria-labelledby={`cmp-tab-${kind}`} className="mt-6">
          <p className={cn("eyebrow", kind === "planet" ? "text-star" : "text-ice")}>{current.verdict}</p>
          <p className="mt-2 text-lg leading-snug">{current.text}</p>
          <p className="mt-3 text-sm leading-relaxed text-muted-foreground"><span className="text-foreground">The tell: </span>{current.tell}</p>
        </div>
      </div>
      <figure className="glass rounded-2xl p-3 sm:p-4">
        <svg viewBox={`0 0 ${W} 300`} role="img" className="h-auto w-full"
             aria-label={`Illustration of a ${current.label.toLowerCase()} and the light curve it produces. ${current.tell}`}>
          <defs>
            <radialGradient id="cmp-star" cx="45%" cy="42%" r="60%">
              <stop offset="0%" stopColor="#ffd08a" /><stop offset="60%" stopColor="#f2711c" /><stop offset="100%" stopColor="#9a3412" />
            </radialGradient>
            <radialGradient id="cmp-star-cool" cx="45%" cy="42%" r="60%">
              <stop offset="0%" stopColor="#ffe9c4" /><stop offset="70%" stopColor="#f59e0b" /><stop offset="100%" stopColor="#92400e" />
            </radialGradient>
          </defs>
          <Scene kind={kind} phase={phase} />
          <line x1={GRAPH.x} x2={GRAPH.x + GRAPH.w} y1={GRAPH.y + 10} y2={GRAPH.y + 10} stroke="rgba(255,255,255,0.08)" />
          <path d={curve} fill="none" stroke="#f2f3f5" strokeWidth="1.5" />
          <line x1={GRAPH.x + phase * GRAPH.w} x2={GRAPH.x + phase * GRAPH.w} y1={GRAPH.y} y2={GRAPH.y + GRAPH.h}
                stroke="rgba(243,180,90,0.35)" />
          <circle cx={GRAPH.x + phase * GRAPH.w} cy={markerY} r="4" fill="#f3b45a" />
          <text x={GRAPH.x} y={GRAPH.y + GRAPH.h + 16} fill="#a3a6ad" fontSize="10" fontFamily="var(--font-geist-mono), monospace">one cycle</text>
          <text x={GRAPH.x + GRAPH.w} y={GRAPH.y + GRAPH.h + 16} fill="#a3a6ad" fontSize="10" textAnchor="end"
                fontFamily="var(--font-geist-mono), monospace">same depth scale for all four</text>
        </svg>
        <figcaption className="mt-1 flex flex-wrap items-center justify-between gap-2 px-1 text-xs text-muted-foreground">
          <span>Illustration. Shapes are realistic in kind, depths are exaggerated.</span>
          <ProvenanceBadge kind="synthetic" />
        </figcaption>
      </figure>
    </div>
  );
}
